export interface LibraryState { readonly collections: readonly Collection[]; readonly readers: readonly Reader[]; }
export interface BookmarkChange { readonly collectionCode: string; readonly articleId: string; readonly readerId: string; readonly heading: string; readonly body: string; readonly bookmarkDelta: -1 | 0 | 1; readonly revision: string; }
export interface UpdateSuccess { readonly ok: true; readonly state: LibraryState; readonly revision: string; }
export interface UpdateFailure { readonly ok: false; readonly state: LibraryState; readonly status: 400 | 404; }
export type UpdateResult = UpdateSuccess | UpdateFailure;

export function applyArticleUpdate(state: LibraryState, change: BookmarkChange): UpdateResult {
  const code = change.collectionCode.trim();
  const articleId = change.articleId.trim();
  const readerId = change.readerId.trim();
  const heading = change.heading.trim();
  const body = change.body.trim();
  const revision = change.revision.trim();

  if (!code || !articleId || !readerId || !heading || !body || !revision ||
      ![-1, 0, 1].includes(change.bookmarkDelta)) {
    return { ok: false, state, status: 400 };
  }

  const collectionIndex = state.collections.findIndex(item => item.code === code);
  if (collectionIndex < 0) return { ok: false, state, status: 404 };

  const collection = state.collections[collectionIndex];
  const articleIndex = collection.articles.findIndex(item => item.id === articleId);
  if (articleIndex < 0) return { ok: false, state, status: 404 };

  const article = collection.articles[articleIndex];
  let readerIndex = -1;

  if (change.bookmarkDelta !== 0) {
    readerIndex = state.readers.findIndex(item => item.id === readerId);
    if (readerIndex < 0) return { ok: false, state, status: 404 };

    const hasBookmark = state.readers[readerIndex].bookmarkedArticleIds.includes(articleId);
    if ((change.bookmarkDelta === 1 && hasBookmark) ||
        (change.bookmarkDelta === -1 && !hasBookmark) ||
        article.bookmarkCount + change.bookmarkDelta < 0) {
      return { ok: false, state, status: 400 };
    }
  }

  const updatedArticle: Article = {
    ...article,
    heading,
    body,
    revision,
    bookmarkCount: article.bookmarkCount + Math.abs(change.bookmarkDelta),
  };
  const articles = collection.articles.map((item, index) => index === articleIndex ? updatedArticle : item);
  const collections = state.collections.map((item, index) => index === collectionIndex ? { ...item, articles } : item);
  const readers = change.bookmarkDelta === 0
    ? [...state.readers]
    : state.readers.map((reader, index) => {
        if (index !== readerIndex) return reader;
        const ids = change.bookmarkDelta === 1
          ? [...reader.bookmarkedArticleIds, articleId]
          : reader.bookmarkedArticleIds.filter(id => id !== articleId);
        return { ...reader, bookmarkedArticleIds: ids };
      });

  return { ok: true, state: { collections, readers }, revision };
}

