import { applyArticleUpdate, LibraryState, BookmarkChange } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

const state = {
  collections: [
    {
      code: 'tech',
      articles: [
        { id: 'a1', heading: 'Old heading', body: 'Old body', bookmarkCount: 1 },
        { id: 'a2', heading: 'Second', body: 'Body two', bookmarkCount: 0 },
      ],
    },
    { code: 'other', articles: [{ id: 'b1', heading: 'B', body: 'B body', bookmarkCount: 0 }] },
  ],
  readers: [
    { id: 'r1', bookmarkedArticleIds: ['a1'] },
    { id: 'r2', bookmarkedArticleIds: [] },
  ],
} as unknown as LibraryState;

const originalText = JSON.stringify(state);
const baseChange = {
  collectionCode: ' tech ',
  articleId: ' a2 ',
  readerId: ' r2 ',
  heading: ' New heading ',
  body: ' New body ',
  revision: ' rev-2 ',
  bookmarkDelta: 1,
} as unknown as BookmarkChange;

const added = applyArticleUpdate(state, baseChange) as unknown as Record<string, unknown>;
assert(added.ok === true, 'valid bookmark addition should succeed');
assert(added.revision === 'rev-2', 'success should return the trimmed supplied revision');
const addedState = added.state as unknown as {
  collections: Array<{ code: string; articles: Array<{ id: string; heading: string; body: string; bookmarkCount: number }> }>;
  readers: Array<{ id: string; bookmarkedArticleIds: string[] }>;
};
assert(addedState !== state, 'success should return a new state');
assert(addedState.collections.map(item => item.code).join(',') === 'tech,other', 'collection order should be preserved');
assert(addedState.collections[0].articles.map(item => item.id).join(',') === 'a1,a2', 'article order should be preserved');
assert(addedState.readers.map(item => item.id).join(',') === 'r1,r2', 'reader order should be preserved');
assert(addedState.collections[0].articles[1].heading === 'New heading', 'heading should be trimmed and updated');
assert(addedState.collections[0].articles[1].body === 'New body', 'body should be trimmed and updated');
assert(addedState.collections[0].articles[1].bookmarkCount === 1, 'bookmark count should increase');
assert(addedState.readers[1].bookmarkedArticleIds.join(',') === 'a2', 'reader bookmarks should be updated');
assert(JSON.stringify(state) === originalText, 'the input state must not be mutated');

addedState.collections[0].articles[1].heading = 'damaged';
addedState.readers[1].bookmarkedArticleIds.push('damaged');
assert(JSON.stringify(state) === originalText, 'mutating a successful result must not affect the input');

const removed = applyArticleUpdate(state, {
  collectionCode: 'tech', articleId: 'a1', readerId: 'r1', heading: 'Revised', body: 'Revised body', revision: 'rev-3', bookmarkDelta: -1,
} as unknown as BookmarkChange) as unknown as Record<string, unknown>;
assert(removed.ok === true, 'an existing bookmark should be removable');
const removedState = removed.state as typeof addedState;
assert(removedState.collections[0].articles[0].bookmarkCount === 0, 'bookmark count should decrease to zero');
assert(removedState.readers[0].bookmarkedArticleIds.length === 0, 'removed bookmark should leave the reader list');

const noReaderNeeded = applyArticleUpdate(state, {
  collectionCode: 'tech', articleId: 'a2', readerId: 'missing', heading: 'Only text', body: 'Only body', revision: 'rev-4', bookmarkDelta: 0,
} as unknown as BookmarkChange) as unknown as Record<string, unknown>;
assert(noReaderNeeded.ok === true, 'delta zero should not require an existing reader');

function expectFailure(change: Record<string, unknown>, status: number, message: string): void {
  const result = applyArticleUpdate(state, change as unknown as BookmarkChange) as unknown as Record<string, unknown>;
  assert(result.ok === false && result.status === status, message);
  assert(result.state === state, message + ': failure should return the original state');
  assert(JSON.stringify(state) === originalText, message + ': failure must not mutate state');
}

for (const field of ['collectionCode', 'articleId', 'readerId', 'heading', 'body', 'revision']) {
  expectFailure({ ...(baseChange as unknown as Record<string, unknown>), [field]: '   ' }, 400, 'blank strings should be rejected');
}
for (const delta of [-2, 0.5, 2, Number.NaN]) {
  expectFailure({ ...(baseChange as unknown as Record<string, unknown>), bookmarkDelta: delta }, 400, 'invalid deltas should be rejected');
}
expectFailure({ ...(baseChange as unknown as Record<string, unknown>), collectionCode: 'missing' }, 404, 'missing collection should return 404');
expectFailure({ ...(baseChange as unknown as Record<string, unknown>), articleId: 'missing' }, 404, 'missing article should return 404');
expectFailure({ ...(baseChange as unknown as Record<string, unknown>), readerId: 'missing' }, 404, 'bookmark changes require an existing reader');
expectFailure({ ...(baseChange as unknown as Record<string, unknown>), articleId: 'a1', readerId: 'r1' }, 400, 'duplicate bookmark addition should fail');
expectFailure({ ...(baseChange as unknown as Record<string, unknown>), bookmarkDelta: -1 }, 400, 'removing a bookmark not held by the reader should fail');

